<script setup lang="ts">import {computed} from 'vue';import {date} from './lib';const props=defineProps<{capacity:Record<string,any>,helper:Record<string,any>}>();const metrics=computed(()=>[{label:'星枢现存身份',value:props.capacity.identities,note:'实现上限 '+(props.capacity.identity_limit??'—')+'，含其他面板身份'},{label:'已核验订单',value:props.capacity.paid_orders,note:'付款已确认，含续费订单'},{label:'当前有效订阅',value:props.capacity.portal_services,note:'身份启用、未到期且额度可用'},{label:'注册客户',value:props.capacity.registered_customers,note:'未删除的注册客户，含待验证及停用'}]);const resources=computed(()=>[{label:'应用容器',value:props.helper.app_resources},{label:'数据库容器',value:props.helper.db_resources},{label:'安装盘可用 / 总容量',value:props.helper.disk_available},{label:'星枢兼容状态',value:props.helper.control_compatibility}]);</script>
<template><section class="panel capacity-panel"><h3>资源与接入容量</h3><p v-if="capacity.error" class="alert error">{{capacity.error}}</p><div class="capacity-metrics"><article v-for="m in metrics" :key="m.label"><span>{{m.label}}</span><strong>{{m.value??'—'}}</strong><small>{{m.note}}</small></article></div><p class="muted">失效服务 {{capacity.invalid_services??'—'}} 份 · 待同步 {{capacity.unchecked_services??'—'}} 份 · 最近验证 {{date(capacity.services_checked_at)}}</p><p v-if="capacity.sync_warning" class="alert">{{capacity.sync_warning}}</p><dl class="capacity-resources"><div v-for="r in resources" :key="r.label"><dt>{{r.label}}</dt><dd>{{r.value||'等待采样'}}</dd></div></dl><p class="muted capacity-note">应用容器上限 256 MiB，数据库 512 MiB，每分钟采样。这些数据用于了解资源使用情况；身份数量上限不代表同时在线承载能力，需结合节点与实际负载评估。</p></section></template>
<style scoped>.capacity-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:18px 0}.capacity-metrics article{min-width:0;padding:17px;border:1px solid var(--border);border-radius:12px;background:var(--surface-soft)}.capacity-metrics span{font-size:12px;color:var(--muted)}.capacity-metrics strong{display:block;font-size:28px;line-height:1.2;margin:9px 0;overflow-wrap:anywhere}.capacity-metrics small{display:block;line-height:1.6;font-size:10px}.capacity-resources{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:18px 0}.capacity-resources>div{padding:14px 16px;background:var(--surface-soft);border:1px solid var(--border);border-radius:10px;min-width:0}.capacity-resources dt{font-size:11px;margin-bottom:8px}.capacity-resources dd{margin:0;font-family:ui-monospace,monospace;font-size:12px;line-height:1.7;overflow-wrap:anywhere;white-space:pre-wrap}.capacity-note{font-size:11px;line-height:1.8}@media(max-width:1100px){.capacity-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:760px){.capacity-metrics{gap:9px}.capacity-metrics article{padding:13px}.capacity-metrics strong{font-size:24px}.capacity-resources{grid-template-columns:1fr}.capacity-panel>p{font-size:11px;line-height:1.8}}</style>
